import React, { useState, useEffect } from 'react';

// Import chuẩn xác 4 màn hình con từ thư mục components của bạn
import MovieList from './components/MovieList';
import ShowtimeScreen from './components/ShowtimeScreen';
import SeatScreen from './components/SeatScreen';
import AuthScreen from './components/AuthScreen';

function App() {
  // Khởi tạo các State để lưu dữ liệu từ database.json ngoài thư mục gốc
  const [movies, setMovies] = useState([]);
  const [showtimes, setShowtimes] = useState([]);
  const [seats, setSeats] = useState([]);
  const [bookings, setBookings] = useState([]);
  const [loading, setLoading] = useState(true);

  // Quản lý chuyển đổi giữa các màn hình
  const [currentScreen, setCurrentScreen] = useState('movie-list');
  const [selectedMovie, setSelectedMovie] = useState(null);
  const [selectedShowtime, setSelectedShowtime] = useState(null);

  useEffect(() => {
    // Mẹo qua mặt Webpack 5: Ghép chuỗi để che giấu ký tự lùi mục "../"
    const pathGoc = ['..', 'database.json'].join('/');

    fetch(`/${pathGoc}`)
      .then((res) => {
        if (!res.ok) {
          throw new Error("Không thể đọc trực tiếp file từ thư mục gốc!");
        }
        return res.json();
      })
      .then((data) => {
        // Đọc dữ liệu thành công từ file database.json gốc của bạn
        setMovies(data.movies || []);
        setShowtimes(data.showtimes || []);
        setSeats(data.seats || []);
        setBookings(data.bookings || []);
        setLoading(false);
      })
      .catch((err) => {
        console.warn("Đang thử phương thức kết nối dự phòng...", err);
        // Cách dự phòng nếu trình duyệt chạy ở môi trường đặc biệt
        fetch(window.location.origin + '/database.json')
          .then((res) => res.json())
          .then((data) => {
            setMovies(data.movies || []);
            setShowtimes(data.showtimes || []);
            setSeats(data.seats || []);
            setBookings(data.bookings || []);
            setLoading(false);
          })
          .catch((error) => {
            console.error("Thất bại khi kết nối tới database.json:", error);
            setLoading(false);
          });
      });
  }, []);

  // Hiển thị màn hình chờ khi dữ liệu đang được nạp vào hệ thống
  if (loading) {
    return (
      <div className="d-flex justify-content-center align-items-center min-vh-100 bg-light">
        <div className="text-center">
          <div className="spinner-border text-warning mb-2" role="status"></div>
          <h5 className="fw-bold text-secondary">Đang kết nối database ngoài thư mục gốc...</h5>
        </div>
      </div>
    );
  }

  return (
    <div className="bg-light min-vh-100 pb-5">
      {/* THANH NAVBAR CHUNG CỦA HỆ THỐNG */}
      <nav className="navbar navbar-dark bg-dark mb-5 shadow">
        <div className="container">
          <span 
            className="navbar-brand mb-0 h1 fw-bold text-warning fs-3" 
            style={{ cursor: 'pointer', letterSpacing: '1px' }} 
            onClick={() => setCurrentScreen('movie-list')}
          >
            🎬 BETA CINEMA
          </span>
          {selectedMovie && currentScreen !== 'movie-list' && (
            <span className="text-white-50 d-none d-sm-inline">
              Phim đang chọn: <strong className="text-white">{selectedMovie.title}</strong>
            </span>
          )}
        </div>
      </nav>

      {/* KHU VỰC ĐIỀU HƯỚNG HIỂN THỊ CÁC MÀN HÌNH CHỨC NĂNG */}
      <div className="container">
        {/* 1. MÀN HÌNH TRANG CHỦ / DANH SÁCH PHIM */}
        {currentScreen === 'movie-list' && (
          <MovieList 
            movies={movies} 
            showtimes={showtimes}
            onSelectMovie={(movie) => { 
              setSelectedMovie(movie); 
              setCurrentScreen('showtime-list'); 
            }}
            onGoToAuth={() => setCurrentScreen('auth')}
          />
        )}

        {/* 2. MÀN HÌNH CHỌN SUẤT CHIẾU (GIỜ CHIẾU) */}
        {currentScreen === 'showtime-list' && (
          <ShowtimeScreen 
            movie={selectedMovie} 
            showtimes={showtimes} 
            onSelectShowtime={(st) => { 
              setSelectedShowtime(st); 
              setCurrentScreen('seat-plan'); 
            }}
            onBack={() => setCurrentScreen('movie-list')} 
          />
        )}

        {/* 3. MÀN HÌNH SƠ ĐỒ GHẾ NGỒI VÀ TÍNH TIỀN */}
        {currentScreen === 'seat-plan' && (
          <SeatScreen 
            showtime={selectedShowtime} 
            movie={selectedMovie}
            seats={seats}
            bookings={bookings}
            onBookingSuccess={(newBookings) => setBookings([...bookings, ...newBookings])}
            onBack={() => setCurrentScreen('showtime-list')}
          />
        )}

        {/* 4. MÀN HÌNH ĐĂNG NHẬP / ĐĂNG KÝ */}
        {currentScreen === 'auth' && (
          <AuthScreen onBack={() => setCurrentScreen('movie-list')} />
        )}
      </div>
    </div>
  );
}

export default App;
